# ============================================
# MEMORY MANAGEMENT SYSTEM
# ============================================

class MemoryManager:
    """Centralized memory management for TensorFlow/Keras models"""
    
    @staticmethod
    def initialize():
        """Initialize TensorFlow with memory optimizations"""
        try:
            # Clear any existing sessions
            K.clear_session()
            tf.compat.v1.reset_default_graph()
            
            # Configure GPU memory growth
            gpus = tf.config.experimental.list_physical_devices('GPU')
            if gpus:
                for gpu in gpus:
                    tf.config.experimental.set_memory_growth(gpu, True)
                print(f"✓ GPU memory growth enabled on {len(gpus)} GPU(s)")
            
            # Set mixed precision if available
            try:
                policy = tf.keras.mixed_precision.Policy('mixed_float16')
                tf.keras.mixed_precision.set_global_policy(policy)
                print("✓ Mixed precision enabled")
            except:
                pass
                
            # Optimize TensorFlow performance
            tf.config.threading.set_intra_op_parallelism_threads(2)
            tf.config.threading.set_inter_op_parallelism_threads(2)
            
        except Exception as e:
            print(f"⚠ Memory initialization warning: {e}")
    
    @staticmethod
    def cleanup():
        """Force cleanup of memory"""
        gc.collect()
        K.clear_session()
        tf.compat.v1.reset_default_graph()
    
    @staticmethod
    def get_memory_usage():
        """Get current memory usage in MB"""
        process = psutil.Process(os.getpid())
        return process.memory_info().rss / 1024 ** 2
    
    @staticmethod
    def validate_data(X_train, y_train, X_val, y_val):
        """Validate data shapes and clean data"""
        print("📊 Data Validation:")
        
        # Check shapes
        print(f"  X_train shape: {X_train.shape}")
        print(f"  y_train shape: {y_train.shape}")
        print(f"  X_val shape: {X_val.shape}")
        print(f"  y_val shape: {y_val.shape}")
        
        # Validate 3D shape for sequence models
        if len(X_train.shape) != 3:
            raise ValueError(f"X_train must be 3D (samples, timesteps, features). Got: {X_train.shape}")
        
        # Check for NaN/Inf
        train_nan = np.isnan(X_train).sum()
        train_inf = np.isinf(X_train).sum()
        
        if train_nan > 0 or train_inf > 0:
            print(f"  ⚠ Cleaning {train_nan} NaN and {train_inf} Inf values")
            X_train = np.nan_to_num(X_train, nan=0.0, posinf=1.0, neginf=-1.0)
            X_val = np.nan_to_num(X_val, nan=0.0, posinf=1.0, neginf=-1.0)
        
        # Check sequence length
        if X_train.shape[1] > 500:
            print(f"  ⚠ Long sequence length: {X_train.shape[1]}. Consider reducing.")
        
        # Check class balance
        unique, counts = np.unique(y_train, return_counts=True)
        if len(unique) == 2:
            ratio = counts[1] / counts[0] if counts[0] > 0 else float('inf')
            if ratio < 0.2 or ratio > 5:
                print(f"  ⚠ Class imbalance detected: Class 0={counts[0]}, Class 1={counts[1]}")
        
        print("  ✓ Data validation complete")
        return X_train, X_val
    
    @staticmethod
    def calculate_safe_batch_size(X_train, default_batch_size=32):
        """Calculate safe batch size based on data size"""
        n_samples = len(X_train)
        seq_length = X_train.shape[1]
        n_features = X_train.shape[2]
        
        # Estimate memory per sample
        estimated_memory_per_sample = seq_length * n_features * 4  # 4 bytes per float32
        
        # Calculate safe batch size
        safe_batch = min(default_batch_size, n_samples // 4)
        safe_batch = max(8, safe_batch)  # Minimum batch size
        
        # Adjust based on sequence length
        if seq_length > 100:
            safe_batch = max(8, safe_batch // 2)
        
        return safe_batch

# ============================================
# UPDATED BASE MODEL WITH ROBUST ERROR HANDLING
# ============================================

class BaseModel:
    """Enhanced Base class for all models with robust error handling"""

    def __init__(self, name):
        self.name = name
        self.model = None
        self.predictions = {}
        self.metrics = {}
        self.history = None
        self.threshold = 0.5
        self.feature_importance = None
        self.model_summary = ""
        self.is_trained = False
        self.training_error = None
        
        # Enhanced training history
        self.training_history = {
            'epochs': [],
            'train_loss': [],
            'val_loss': [],
            'train_accuracy': [],
            'val_accuracy': [],
            'train_metrics': {},
            'val_metrics': {},
            'learning_rates': [],
            'batch_sizes': []
        }

    def __del__(self):
        """Cleanup when object is destroyed"""
        self.cleanup()

    def cleanup(self):
        """Clean up model resources"""
        try:
            if self.model is not None:
                if hasattr(self.model, '_is_graph_network'):
                    del self.model
                self.model = None
            MemoryManager.cleanup()
        except:
            pass

    def train(self, X_train, y_train, X_val, y_val):
        """Train the model - to be implemented by subclasses"""
        raise NotImplementedError

    def predict(self, X):
        """Make predictions - to be implemented by subclasses"""
        raise NotImplementedError

    def safe_predict(self, X, batch_size=None):
        """Safe prediction with error handling"""
        try:
            if not self.is_trained:
                raise ValueError(f"Model {self.name} is not trained")
            
            if batch_size is None:
                batch_size = min(BATCH_SIZE, len(X))
            
            return self.predict(X)
        except Exception as e:
            print(f"⚠ Prediction error in {self.name}: {e}")
            # Return safe fallback predictions
            return np.full(len(X), 0.5)

    def evaluate(self, y_true, y_pred, set_name="Validation", find_threshold=False):
        """Enhanced evaluation with robust error handling"""
        try:
            # Clip predictions to avoid numerical issues
            y_pred = np.clip(y_pred, 1e-7, 1 - 1e-7)
            
            # Find optimal threshold if requested
            if find_threshold and len(y_true) > 0:
                optimal_threshold = self.find_optimal_threshold(y_true, y_pred)
                if optimal_threshold is not None:
                    self.threshold = optimal_threshold
            
            # Convert to binary
            y_true_binary = (y_true > 0.5).astype(int)
            y_pred_binary = (y_pred > self.threshold).astype(int) if len(y_pred) > 0 else np.array([])
            
            # Calculate metrics with error handling
            metrics = self._calculate_metrics(y_true, y_pred, y_true_binary, y_pred_binary)
            
            # Store and display metrics
            self._store_and_display_metrics(metrics, set_name)
            
            return metrics, y_true_binary, y_pred_binary
            
        except Exception as e:
            print(f"⚠ Evaluation error in {self.name}: {e}")
            # Return default metrics
            default_metrics = self._get_default_metrics()
            return default_metrics, np.array([]), np.array([])

    def _calculate_metrics(self, y_true, y_pred, y_true_binary, y_pred_binary):
        """Calculate all metrics with error handling"""
        metrics = {
            'MAE': 0, 'RMSE': 0, 'R2': 0, 'Accuracy': 0,
            'Precision': 0, 'Recall': 0, 'F1': 0,
            'AUC_ROC': 0.5, 'Threshold': self.threshold
        }
        
        try:
            # Regression metrics
            if len(y_true) > 0:
                metrics['MAE'] = mean_absolute_error(y_true, y_pred)
                metrics['RMSE'] = np.sqrt(mean_squared_error(y_true, y_pred))
                if len(np.unique(y_true)) > 1:
                    metrics['R2'] = r2_score(y_true, y_pred)
            
            # Classification metrics
            if (len(y_true_binary) > 0 and len(y_pred_binary) > 0 and 
                len(np.unique(y_true_binary)) > 1):
                metrics['Accuracy'] = accuracy_score(y_true_binary, y_pred_binary)
                metrics['Precision'] = precision_score(y_true_binary, y_pred_binary, zero_division=0)
                metrics['Recall'] = recall_score(y_true_binary, y_pred_binary, zero_division=0)
                metrics['F1'] = f1_score(y_true_binary, y_pred_binary, zero_division=0)
                
                # AUC with error handling
                try:
                    metrics['AUC_ROC'] = roc_auc_score(y_true_binary, y_pred)
                except:
                    metrics['AUC_ROC'] = 0.5
                    
        except Exception as e:
            print(f"⚠ Metric calculation error: {e}")
            
        return metrics

    def _store_and_display_metrics(self, metrics, set_name):
        """Store metrics and display results"""
        self.metrics[set_name] = metrics
        
        print(f"\n{'='*60}")
        print(f"{self.name} - {set_name} Set Evaluation:")
        print(f"{'='*60}")
        
        for metric, value in metrics.items():
            if metric != 'Threshold':
                if isinstance(value, float):
                    print(f"{metric}: {value:.4f}")
                else:
                    print(f"{metric}: {value}")
        
        # Store in training history
        if set_name.lower() == 'train':
            self.training_history['train_metrics'] = metrics
        elif set_name.lower() == 'validation':
            self.training_history['val_metrics'] = metrics

    def _get_default_metrics(self):
        """Get default metrics for error cases"""
        return {
            'MAE': 0, 'RMSE': 0, 'R2': 0, 'Accuracy': 0,
            'Precision': 0, 'Recall': 0, 'F1': 0,
            'AUC_ROC': 0.5, 'Threshold': self.threshold
        }

    def find_optimal_threshold(self, y_true, y_pred_proba):
        """Find optimal threshold with robust error handling"""
        try:
            thresholds = np.arange(0.1, 0.9, 0.05)
            best_threshold = 0.5
            best_f1 = 0

            y_true_binary = (y_true > 0.5).astype(int)
            
            for threshold in thresholds:
                y_pred_binary = (y_pred_proba > threshold).astype(int)
                if len(np.unique(y_pred_binary)) > 1:
                    try:
                        f1 = f1_score(y_true_binary, y_pred_binary, zero_division=0)
                        if f1 > best_f1:
                            best_f1 = f1
                            best_threshold = threshold
                    except:
                        continue
            
            return best_threshold
        except:
            return 0.5

    def get_model_summary(self):
        """Get model summary with error handling"""
        try:
            if self.model is not None:
                if hasattr(self.model, 'summary'):
                    string_list = []
                    self.model.summary(print_fn=lambda x: string_list.append(x))
                    self.model_summary = "\n".join(string_list)
                elif hasattr(self.model, 'get_params'):
                    params = self.model.get_params()
                    self.model_summary = f"{self.name} Parameters:\n"
                    for key, value in params.items():
                        self.model_summary += f"  {key}: {value}\n"
                else:
                    self.model_summary = f"{self.name} model is loaded"
            else:
                self.model_summary = f"{self.name} model is not initialized"
                
            return self.model_summary
        except Exception as e:
            return f"Error getting model summary: {e}"

# ============================================
# ALL INDIVIDUAL MODELS (UPDATED WITH MEMORY SAFETY)
# ============================================

class LSTMModel(BaseModel):
    """LSTM Model with Attention and Memory Safety"""

    def __init__(self):
        super().__init__("LSTM")
        self.architecture_info = {
            'type': 'LSTM',
            'layers': [
                {'type': 'Input', 'shape': 'variable'},
                {'type': 'LSTM', 'units': LSTM_UNITS, 'return_sequences': True},
                {'type': 'BatchNormalization'},
                {'type': 'Attention'},
                {'type': 'LayerNormalization'},
                {'type': 'GlobalAveragePooling1D'},
                {'type': 'BatchNormalization'}
            ]
        }
        for units in DENSE_UNITS:
            self.architecture_info['layers'].extend([
                {'type': 'Dense', 'units': units, 'activation': 'relu'},
                {'type': 'Dropout', 'rate': DROPOUT_RATE},
                {'type': 'BatchNormalization'}
            ])
        self.architecture_info['layers'].append({'type': 'Dense', 'units': 1, 'activation': 'sigmoid'})

    def build_model(self, input_shape):
        """Build LSTM model with memory optimization"""
        try:
            print(f"  Building LSTM model with input shape: {input_shape}")
            
            inputs = Input(shape=input_shape)
            
            # LSTM layer with memory optimizations
            lstm_out = LSTM(
                LSTM_UNITS, 
                return_sequences=True,
                dropout=DROPOUT_RATE,
                recurrent_dropout=RECURRENT_DROPOUT,
                kernel_initializer='glorot_uniform',
                recurrent_initializer='orthogonal'
            )(inputs)
            lstm_out = BatchNormalization()(lstm_out)
            
            # Attention mechanism
            attention = Attention()([lstm_out, lstm_out])
            attention = LayerNormalization()(attention)
            
            # Global pooling
            pooled = GlobalAveragePooling1D()(attention)
            pooled = BatchNormalization()(pooled)

            # Dense layers
            x = pooled
            for units in DENSE_UNITS:
                x = Dense(
                    units, 
                    activation='relu',
                    kernel_initializer='he_normal'
                )(x)
                x = Dropout(DROPOUT_RATE)(x)
                x = BatchNormalization()(x)

            # Output layer
            outputs = Dense(1, activation='sigmoid')(x)

            # Create model
            model = Model(inputs=inputs, outputs=outputs)
            
            # Optimizer with gradient clipping for stability
            optimizer = Adam(
                learning_rate=LEARNING_RATE,
                clipnorm=1.0,
                # clipvalue=0.5
            )
            
            # Compile model
            model.compile(
                optimizer=optimizer,
                loss='binary_crossentropy',
                metrics=[
                    'accuracy',
                    tf.keras.metrics.AUC(name='auc'),
                    tf.keras.metrics.Precision(name='precision'),
                    tf.keras.metrics.Recall(name='recall')
                ]
            )
            
            print(f"  ✓ LSTM model built successfully")
            return model
            
        except Exception as e:
            print(f"  ✗ Error building LSTM model: {e}")
            raise

    def train(self, X_train, y_train, X_val, y_val):
        """Train LSTM model with comprehensive error handling"""
        print(f"\n{'='*60}")
        print(f"🚀 Training {self.name} Model")
        print(f"{'='*60}")
        
        try:
            # Step 1: Memory initialization
            MemoryManager.initialize()
            memory_start = MemoryManager.get_memory_usage()
            print(f"  Memory at start: {memory_start:.2f} MB")
            
            # Step 2: Validate and clean data
            print("  Validating data...")
            X_train, X_val = MemoryManager.validate_data(X_train, y_train, X_val, y_val)
            
            # Step 3: Calculate safe batch size
            safe_batch_size = MemoryManager.calculate_safe_batch_size(X_train, BATCH_SIZE)
            print(f"  Using batch size: {safe_batch_size}")
            
            # Step 4: Build model
            print("  Building model architecture...")
            self.model = self.build_model((X_train.shape[1], X_train.shape[2]))
            
            # Step 5: Test model with small batch
            print("  Testing model with small batch...")
            test_batch = min(4, len(X_train))
            test_pred = self.model.predict(X_train[:test_batch], verbose=0, batch_size=test_batch)
            print(f"  ✓ Test prediction successful (shape: {test_pred.shape})")
            
            # Step 6: Setup callbacks
            callbacks = [
                EarlyStopping(
                    monitor='val_loss',
                    patience=PATIENCE,
                    restore_best_weights=True,
                    verbose=1,
                    min_delta=0.001
                ),
                ReduceLROnPlateau(
                    monitor='val_loss',
                    factor=0.5,
                    patience=PATIENCE // 2,
                    verbose=1,
                    min_lr=1e-6
                ),
                TerminateOnNaN(),
                ModelCheckpoint(
                    f'checkpoints/best_{self.name.lower()}.weights.h5',
                    monitor='val_loss',
                    save_best_only=True,
                    save_weights_only=True,
                    verbose=0
                )
            ]
            
            # Step 7: Train model
            print(f"  Starting training ({len(X_train)} samples)...")
            self.history = self.model.fit(
                X_train, y_train,
                validation_data=(X_val, y_val),
                epochs=EPOCHS,
                batch_size=safe_batch_size,
                callbacks=callbacks,
                verbose=1,
                shuffle=True
            )
            
            # Step 8: Store training history
            if self.history is not None:
                self._store_training_history()
                print(f"  ✓ Training completed in {len(self.history.history['loss'])} epochs")
            
            # Step 9: Make predictions
            print("  Generating predictions...")
            self.predictions['train'] = self.model.predict(
                X_train, verbose=0, batch_size=safe_batch_size
            ).flatten()
            
            self.predictions['val'] = self.model.predict(
                X_val, verbose=0, batch_size=safe_batch_size
            ).flatten()
            
            # Step 10: Evaluate
            print("  Evaluating model...")
            self.evaluate(y_train, self.predictions['train'], "Train", find_threshold=True)
            self.evaluate(y_val, self.predictions['val'], "Validation")
            
            # Step 11: Update status
            self.is_trained = True
            
            # Step 12: Memory cleanup and reporting
            memory_end = MemoryManager.get_memory_usage()
            print(f"  Memory usage: {memory_end:.2f} MB (Δ: {memory_end - memory_start:+.2f} MB)")
            
            print(f"  ✅ {self.name} training completed successfully!")
            
            return self
            
        except tf.errors.ResourceExhaustedError:
            print(f"  ❗ ERROR: Memory exhausted!")
            print(f"  Suggestions:")
            print(f"    • Reduce LSTM_UNITS (current: {LSTM_UNITS})")
            print(f"    • Reduce sequence length")
            print(f"    • Reduce batch size (current: {BATCH_SIZE})")
            self.training_error = "Memory exhausted"
            return self
            
        except ValueError as e:
            print(f"  ❗ ERROR: Configuration error: {e}")
            self.training_error = str(e)
            return self
            
        except Exception as e:
            print(f"  ❗ ERROR: Unexpected error: {e}")
            import traceback
            traceback.print_exc()
            self.training_error = str(e)
            return self
        finally:
            # Always attempt cleanup
            try:
                MemoryManager.cleanup()
            except:
                pass

    def _store_training_history(self):
        """Store training history from Keras history object"""
        if self.history is not None:
            history = self.history.history
            self.training_history['epochs'] = list(range(1, len(history['loss']) + 1))
            self.training_history['train_loss'] = history['loss']
            self.training_history['val_loss'] = history['val_loss']
            self.training_history['train_accuracy'] = history['accuracy']
            self.training_history['val_accuracy'] = history['val_accuracy']
            
            # Store additional metrics if available
            for key in ['auc', 'precision', 'recall']:
                if key in history:
                    self.training_history[f'train_{key}'] = history[key]
                if f'val_{key}' in history:
                    self.training_history[f'val_{key}'] = history[f'val_{key}']

    def predict(self, X):
        """Make predictions with memory safety"""
        if not self.is_trained:
            raise ValueError(f"{self.name} model is not trained")
        
        try:
            safe_batch_size = MemoryManager.calculate_safe_batch_size(X, BATCH_SIZE)
            return self.model.predict(X, verbose=0, batch_size=safe_batch_size).flatten()
        except Exception as e:
            print(f"⚠ Prediction error: {e}")
            # Return safe fallback
            return np.full(len(X), 0.5)

class BiLSTMModel(BaseModel):
    """Bidirectional LSTM Model with memory safety"""
    
    def __init__(self):
        super().__init__("BiLSTM")
        self.architecture_info = {
            'type': 'BiLSTM',
            'layers': [
                {'type': 'Input', 'shape': 'variable'},
                {'type': 'Bidirectional-LSTM', 'units': BILSTM_UNITS, 'return_sequences': True},
                {'type': 'BatchNormalization'},
                {'type': 'Bidirectional-LSTM', 'units': BILSTM_UNITS//2, 'return_sequences': False},
                {'type': 'BatchNormalization'}
            ]
        }
        for units in DENSE_UNITS:
            self.architecture_info['layers'].extend([
                {'type': 'Dense', 'units': units, 'activation': 'relu'},
                {'type': 'Dropout', 'rate': DROPOUT_RATE},
                {'type': 'BatchNormalization'}
            ])
        self.architecture_info['layers'].append({'type': 'Dense', 'units': 1, 'activation': 'sigmoid'})
    
    def build_model(self, input_shape):
        """Build BiLSTM model"""
        try:
            inputs = Input(shape=input_shape)
            
            # First BiLSTM layer
            bilstm_out = Bidirectional(
                LSTM(
                    BILSTM_UNITS, 
                    return_sequences=True,
                    dropout=DROPOUT_RATE,
                    recurrent_dropout=RECURRENT_DROPOUT,
                    kernel_initializer='glorot_uniform'
                )
            )(inputs)
            bilstm_out = BatchNormalization()(bilstm_out)

            # Second BiLSTM layer
            bilstm_out2 = Bidirectional(
                LSTM(
                    BILSTM_UNITS//2, 
                    return_sequences=False,
                    dropout=DROPOUT_RATE,
                    kernel_initializer='glorot_uniform'
                )
            )(bilstm_out)
            bilstm_out2 = BatchNormalization()(bilstm_out2)

            # Dense layers
            x = bilstm_out2
            for units in DENSE_UNITS:
                x = Dense(units, activation='relu', kernel_initializer='he_normal')(x)
                x = Dropout(DROPOUT_RATE)(x)
                x = BatchNormalization()(x)

            # Output layer
            outputs = Dense(1, activation='sigmoid')(x)

            # Create and compile model
            model = Model(inputs=inputs, outputs=outputs)
            
            optimizer = Adam(
                learning_rate=LEARNING_RATE,
                clipnorm=1.0
            )
            
            model.compile(
                optimizer=optimizer,
                loss='binary_crossentropy',
                metrics=[
                    'accuracy',
                    tf.keras.metrics.AUC(name='auc'),
                    tf.keras.metrics.Precision(name='precision'),
                    tf.keras.metrics.Recall(name='recall')
                ]
            )
            
            return model
            
        except Exception as e:
            print(f"Error building BiLSTM model: {e}")
            raise
    
    def train(self, X_train, y_train, X_val, y_val):
        """Train BiLSTM model with memory safety"""
        print(f"\nTraining {self.name} model...")
        
        try:
            # Initialize memory
            MemoryManager.initialize()
            
            # Validate data
            X_train, X_val = MemoryManager.validate_data(X_train, y_train, X_val, y_val)
            
            # Calculate safe batch size
            safe_batch_size = MemoryManager.calculate_safe_batch_size(X_train, BATCH_SIZE)
            
            # Build model
            self.model = self.build_model((X_train.shape[1], X_train.shape[2]))
            
            # Setup callbacks
            callbacks = [
                EarlyStopping(
                    monitor='val_loss',
                    patience=PATIENCE,
                    restore_best_weights=True,
                    verbose=1
                ),
                ReduceLROnPlateau(
                    monitor='val_loss',
                    factor=0.5,
                    patience=PATIENCE//2,
                    verbose=1
                ),
                TerminateOnNaN()
            ]
            
            # Train model
            self.history = self.model.fit(
                X_train, y_train,
                validation_data=(X_val, y_val),
                epochs=EPOCHS,
                batch_size=safe_batch_size,
                callbacks=callbacks,
                verbose=1,
                shuffle=True
            )
            
            # Store predictions
            self.predictions['train'] = self.model.predict(
                X_train, verbose=0, batch_size=safe_batch_size
            ).flatten()
            
            self.predictions['val'] = self.model.predict(
                X_val, verbose=0, batch_size=safe_batch_size
            ).flatten()
            
            # Store training history
            if self.history is not None:
                self._store_training_history()
            
            # Evaluate
            self.evaluate(y_train, self.predictions['train'], "Train", find_threshold=True)
            self.evaluate(y_val, self.predictions['val'], "Validation")
            
            self.is_trained = True
            print(f"  ✓ {self.name} training completed")
            
            return self
            
        except Exception as e:
            print(f"  ✗ Error training {self.name}: {e}")
            self.training_error = str(e)
            return self
        finally:
            MemoryManager.cleanup()
    
    def _store_training_history(self):
        """Store training history"""
        if self.history is not None:
            history = self.history.history
            self.training_history['epochs'] = list(range(1, len(history['loss']) + 1))
            self.training_history['train_loss'] = history['loss']
            self.training_history['val_loss'] = history['val_loss']
            self.training_history['train_accuracy'] = history['accuracy']
            self.training_history['val_accuracy'] = history['val_accuracy']
    
    def predict(self, X):
        """Make predictions"""
        if not self.is_trained:
            raise ValueError(f"{self.name} model is not trained")
        
        safe_batch_size = MemoryManager.calculate_safe_batch_size(X, BATCH_SIZE)
        return self.model.predict(X, verbose=0, batch_size=safe_batch_size).flatten()

class GRUModel(BaseModel):
    """GRU Model with enhanced memory safety and error handling"""

    def __init__(self):
        super().__init__("GRU")
        self.architecture_info = {
            'type': 'GRU',
            'layers': [
                {'type': 'Input', 'shape': 'variable'},
                {'type': 'GRU', 'units': GRU_UNITS, 'return_sequences': True},
                {'type': 'BatchNormalization'},
                {'type': 'GRU', 'units': GRU_UNITS//2, 'return_sequences': False},
                {'type': 'BatchNormalization'}
            ]
        }
        # Add dense layers
        for units in DENSE_UNITS:
            self.architecture_info['layers'].extend([
                {'type': 'Dense', 'units': units, 'activation': 'relu'},
                {'type': 'Dropout', 'rate': DROPOUT_RATE},
                {'type': 'BatchNormalization'}
            ])
        self.architecture_info['layers'].append({'type': 'Dense', 'units': 1, 'activation': 'sigmoid'})

    def build_model(self, input_shape):
        """Build GRU model with memory optimization"""
        try:
            print(f"  Building GRU model with input shape: {input_shape}")
            
            inputs = Input(shape=input_shape)
            
            # First GRU layer
            gru_out = GRU(
                GRU_UNITS, 
                return_sequences=True,
                dropout=DROPOUT_RATE,
                recurrent_dropout=RECURRENT_DROPOUT,
                kernel_initializer='glorot_uniform',
                recurrent_initializer='orthogonal'
            )(inputs)
            gru_out = BatchNormalization()(gru_out)

            # Second GRU layer
            gru_out2 = GRU(
                GRU_UNITS//2, 
                return_sequences=False,
                dropout=DROPOUT_RATE,
                kernel_initializer='glorot_uniform',
                recurrent_initializer='orthogonal'
            )(gru_out)
            gru_out2 = BatchNormalization()(gru_out2)

            # Dense layers
            x = gru_out2
            for units in DENSE_UNITS:
                x = Dense(
                    units, 
                    activation='relu',
                    kernel_initializer='he_normal'
                )(x)
                x = Dropout(DROPOUT_RATE)(x)
                x = BatchNormalization()(x)

            # Output layer
            outputs = Dense(1, activation='sigmoid')(x)

            # Create model
            model = Model(inputs=inputs, outputs=outputs)
            
            # Optimizer with gradient clipping
            optimizer = Adam(
                learning_rate=LEARNING_RATE,
                clipnorm=1.0
            )
            
            # Compile model
            model.compile(
                optimizer=optimizer,
                loss='binary_crossentropy',
                metrics=[
                    'accuracy',
                    tf.keras.metrics.AUC(name='auc'),
                    tf.keras.metrics.Precision(name='precision'),
                    tf.keras.metrics.Recall(name='recall')
                ]
            )
            
            print(f"  ✓ GRU model built successfully")
            return model
            
        except Exception as e:
            print(f"  ✗ Error building GRU model: {e}")
            raise

    def train(self, X_train, y_train, X_val, y_val):
        """Train GRU model with comprehensive error handling"""
        print(f"\n{'='*60}")
        print(f"🚀 Training {self.name} Model")
        print(f"{'='*60}")
        
        try:
            # Step 1: Memory initialization
            MemoryManager.initialize()
            memory_start = MemoryManager.get_memory_usage()
            print(f"  Memory at start: {memory_start:.2f} MB")
            
            # Step 2: Validate and clean data
            print("  Validating data...")
            X_train, X_val = MemoryManager.validate_data(X_train, y_train, X_val, y_val)
            
            # Step 3: Calculate safe batch size
            safe_batch_size = MemoryManager.calculate_safe_batch_size(X_train, BATCH_SIZE)
            print(f"  Using batch size: {safe_batch_size}")
            
            # Step 4: Build model
            print("  Building model architecture...")
            self.model = self.build_model((X_train.shape[1], X_train.shape[2]))
            
            # Step 5: Test model with small batch
            print("  Testing model with small batch...")
            test_batch = min(4, len(X_train))
            test_pred = self.model.predict(X_train[:test_batch], verbose=0, batch_size=test_batch)
            print(f"  ✓ Test prediction successful (shape: {test_pred.shape})")
            
            # Step 6: Setup callbacks
            callbacks = [
                EarlyStopping(
                    monitor='val_loss',
                    patience=PATIENCE,
                    restore_best_weights=True,
                    verbose=1,
                    min_delta=0.001
                ),
                ReduceLROnPlateau(
                    monitor='val_loss',
                    factor=0.5,
                    patience=PATIENCE // 2,
                    verbose=1,
                    min_lr=1e-6
                ),
                TerminateOnNaN(),
                ModelCheckpoint(
                    f'checkpoints/best_{self.name.lower()}.weights.h5',
                    monitor='val_loss',
                    save_best_only=True,
                    save_weights_only=True,
                    verbose=0
                )
            ]
            
            # Step 7: Train model
            print(f"  Starting training ({len(X_train)} samples)...")
            self.history = self.model.fit(
                X_train, y_train,
                validation_data=(X_val, y_val),
                epochs=EPOCHS,
                batch_size=safe_batch_size,
                callbacks=callbacks,
                verbose=1,
                shuffle=True
            )
            
            # Step 8: Store training history
            if self.history is not None:
                self._store_training_history()
                print(f"  ✓ Training completed in {len(self.history.history['loss'])} epochs")
            
            # Step 9: Make predictions
            print("  Generating predictions...")
            self.predictions['train'] = self.model.predict(
                X_train, verbose=0, batch_size=safe_batch_size
            ).flatten()
            
            self.predictions['val'] = self.model.predict(
                X_val, verbose=0, batch_size=safe_batch_size
            ).flatten()
            
            # Step 10: Evaluate
            print("  Evaluating model...")
            self.evaluate(y_train, self.predictions['train'], "Train", find_threshold=True)
            self.evaluate(y_val, self.predictions['val'], "Validation")
            
            # Step 11: Update status
            self.is_trained = True
            
            # Step 12: Memory cleanup and reporting
            memory_end = MemoryManager.get_memory_usage()
            print(f"  Memory usage: {memory_end:.2f} MB (Δ: {memory_end - memory_start:+.2f} MB)")
            
            print(f"  ✅ {self.name} training completed successfully!")
            
            return self
            
        except tf.errors.ResourceExhaustedError:
            print(f"  ❗ ERROR: Memory exhausted!")
            print(f"  Suggestions:")
            print(f"    • Reduce GRU_UNITS (current: {GRU_UNITS})")
            print(f"    • Reduce sequence length")
            print(f"    • Reduce batch size (current: {BATCH_SIZE})")
            self.training_error = "Memory exhausted"
            return self
            
        except ValueError as e:
            print(f"  ❗ ERROR: Configuration error: {e}")
            self.training_error = str(e)
            return self
            
        except Exception as e:
            print(f"  ❗ ERROR: Unexpected error: {e}")
            import traceback
            traceback.print_exc()
            self.training_error = str(e)
            return self
        finally:
            # Always attempt cleanup
            try:
                MemoryManager.cleanup()
            except:
                pass

    def _store_training_history(self):
        """Store training history from Keras history object"""
        if self.history is not None:
            history = self.history.history
            self.training_history['epochs'] = list(range(1, len(history['loss']) + 1))
            self.training_history['train_loss'] = history['loss']
            self.training_history['val_loss'] = history['val_loss']
            self.training_history['train_accuracy'] = history['accuracy']
            self.training_history['val_accuracy'] = history['val_accuracy']
            
            # Store additional metrics if available
            for key in ['auc', 'precision', 'recall']:
                if key in history:
                    self.training_history[f'train_{key}'] = history[key]
                if f'val_{key}' in history:
                    self.training_history[f'val_{key}'] = history[f'val_{key}']

    def predict(self, X):
        """Make predictions with memory safety"""
        if not self.is_trained:
            raise ValueError(f"{self.name} model is not trained")
        
        try:
            safe_batch_size = MemoryManager.calculate_safe_batch_size(X, BATCH_SIZE)
            return self.model.predict(X, verbose=0, batch_size=safe_batch_size).flatten()
        except Exception as e:
            print(f"⚠ Prediction error: {e}")
            # Return safe fallback
            return np.full(len(X), 0.5)

class CNNLSTMModel(BaseModel):
    """CNN-LSTM Hybrid Model with memory safety"""
    
    def __init__(self):
        super().__init__("CNN-LSTM")
        self.architecture_info = {
            'type': 'CNN-LSTM',
            'layers': [
                {'type': 'Input', 'shape': 'variable'},
                {'type': 'Conv1D', 'filters': CNN_FILTERS[0], 'kernel_size': CNN_KERNEL_SIZE},
                {'type': 'BatchNormalization'},
                {'type': 'MaxPooling1D', 'pool_size': 2},
                {'type': 'Conv1D', 'filters': CNN_FILTERS[1], 'kernel_size': CNN_KERNEL_SIZE},
                {'type': 'BatchNormalization'},
                {'type': 'MaxPooling1D', 'pool_size': 2},
                {'type': 'LSTM', 'units': LSTM_UNITS, 'return_sequences': False},
                {'type': 'BatchNormalization'}
            ]
        }
        for units in DENSE_UNITS:
            self.architecture_info['layers'].extend([
                {'type': 'Dense', 'units': units, 'activation': 'relu'},
                {'type': 'Dropout', 'rate': DROPOUT_RATE},
                {'type': 'BatchNormalization'}
            ])
        self.architecture_info['layers'].append({'type': 'Dense', 'units': 1, 'activation': 'sigmoid'})
    
    def build_model(self, input_shape):
        """Build CNN-LSTM model"""
        try:
            inputs = Input(shape=input_shape)
            
            # CNN layers
            conv1 = Conv1D(
                filters=CNN_FILTERS[0], 
                kernel_size=CNN_KERNEL_SIZE,
                activation='relu', 
                padding='same',
                kernel_initializer='he_normal'
            )(inputs)
            conv1 = BatchNormalization()(conv1)
            conv1 = MaxPooling1D(pool_size=2)(conv1)

            conv2 = Conv1D(
                filters=CNN_FILTERS[1], 
                kernel_size=CNN_KERNEL_SIZE,
                activation='relu', 
                padding='same',
                kernel_initializer='he_normal'
            )(conv1)
            conv2 = BatchNormalization()(conv2)
            conv2 = MaxPooling1D(pool_size=2)(conv2)

            # LSTM layer
            lstm_out = LSTM(
                LSTM_UNITS, 
                return_sequences=False,
                dropout=DROPOUT_RATE,
                kernel_initializer='glorot_uniform'
            )(conv2)
            lstm_out = BatchNormalization()(lstm_out)

            # Dense layers
            x = lstm_out
            for units in DENSE_UNITS:
                x = Dense(units, activation='relu', kernel_initializer='he_normal')(x)
                x = Dropout(DROPOUT_RATE)(x)
                x = BatchNormalization()(x)

            # Output layer
            outputs = Dense(1, activation='sigmoid')(x)

            # Create and compile model
            model = Model(inputs=inputs, outputs=outputs)
            
            optimizer = Adam(
                learning_rate=LEARNING_RATE,
                clipnorm=1.0
            )
            
            model.compile(
                optimizer=optimizer,
                loss='binary_crossentropy',
                metrics=[
                    'accuracy',
                    tf.keras.metrics.AUC(name='auc'),
                    tf.keras.metrics.Precision(name='precision'),
                    tf.keras.metrics.Recall(name='recall')
                ]
            )
            
            return model
            
        except Exception as e:
            print(f"Error building CNN-LSTM model: {e}")
            raise
    
    def train(self, X_train, y_train, X_val, y_val):
        """Train CNN-LSTM model with memory safety"""
        print(f"\nTraining {self.name} model...")
        
        try:
            # Initialize memory
            MemoryManager.initialize()
            
            # Validate data
            X_train, X_val = MemoryManager.validate_data(X_train, y_train, X_val, y_val)
            
            # Calculate safe batch size
            safe_batch_size = MemoryManager.calculate_safe_batch_size(X_train, BATCH_SIZE)
            
            # Build model
            self.model = self.build_model((X_train.shape[1], X_train.shape[2]))
            
            # Setup callbacks
            callbacks = [
                EarlyStopping(
                    monitor='val_loss',
                    patience=PATIENCE,
                    restore_best_weights=True,
                    verbose=1
                ),
                ReduceLROnPlateau(
                    monitor='val_loss',
                    factor=0.5,
                    patience=PATIENCE//2,
                    verbose=1
                ),
                TerminateOnNaN()
            ]
            
            # Train model
            self.history = self.model.fit(
                X_train, y_train,
                validation_data=(X_val, y_val),
                epochs=EPOCHS,
                batch_size=safe_batch_size,
                callbacks=callbacks,
                verbose=1,
                shuffle=True
            )
            
            # Store predictions
            self.predictions['train'] = self.model.predict(
                X_train, verbose=0, batch_size=safe_batch_size
            ).flatten()
            
            self.predictions['val'] = self.model.predict(
                X_val, verbose=0, batch_size=safe_batch_size
            ).flatten()
            
            # Store training history
            if self.history is not None:
                self._store_training_history()
            
            # Evaluate
            self.evaluate(y_train, self.predictions['train'], "Train", find_threshold=True)
            self.evaluate(y_val, self.predictions['val'], "Validation")
            
            self.is_trained = True
            print(f"  ✓ {self.name} training completed")
            
            return self
            
        except Exception as e:
            print(f"  ✗ Error training {self.name}: {e}")
            self.training_error = str(e)
            return self
        finally:
            MemoryManager.cleanup()
    
    def _store_training_history(self):
        """Store training history"""
        if self.history is not None:
            history = self.history.history
            self.training_history['epochs'] = list(range(1, len(history['loss']) + 1))
            self.training_history['train_loss'] = history['loss']
            self.training_history['val_loss'] = history['val_loss']
            self.training_history['train_accuracy'] = history['accuracy']
            self.training_history['val_accuracy'] = history['val_accuracy']
    
    def predict(self, X):
        """Make predictions"""
        if not self.is_trained:
            raise ValueError(f"{self.name} model is not trained")
        
        safe_batch_size = MemoryManager.calculate_safe_batch_size(X, BATCH_SIZE)
        return self.model.predict(X, verbose=0, batch_size=safe_batch_size).flatten()

class XGBoostModel(BaseModel):
    """XGBoost Model with robust error handling"""
    
    def __init__(self):
        super().__init__("XGBoost")
        self.evals_result = None
        self.architecture_info = {
            'type': 'XGBoost',
            'parameters': {
                'learning_rate': XGB_LEARNING_RATE,
                'max_depth': XGB_MAX_DEPTH,
                'n_estimators': XGB_N_ESTIMATORS,
                'subsample': XGB_SUBSAMPLE,
                'colsample_bytree': XGB_COLSAMPLE_BYTREE
            },
            'description': 'Gradient Boosting with decision trees'
        }
    
    def train(self, X_train, y_train, X_val, y_val):
        """Train XGBoost model with error handling"""
        print(f"\nTraining {self.name} model...")
        
        try:
            # Flatten input for XGBoost
            X_train_flat = X_train.reshape(X_train.shape[0], -1)
            X_val_flat = X_val.reshape(X_val.shape[0], -1)

            # Convert to binary
            y_train_binary = (y_train > 0.5).astype(int)
            y_val_binary = (y_val > 0.5).astype(int)

            # Create the model
            self.model = XGBClassifier(
                learning_rate=XGB_LEARNING_RATE,
                max_depth=XGB_MAX_DEPTH,
                n_estimators=XGB_N_ESTIMATORS,
                subsample=XGB_SUBSAMPLE,
                colsample_bytree=XGB_COLSAMPLE_BYTREE,
                random_state=42,
                verbosity=0,
                n_jobs=-1
            )

            # Fit the model
            self.model.fit(
                X_train_flat, y_train_binary,
                eval_set=[(X_train_flat, y_train_binary), (X_val_flat, y_val_binary)],
                verbose=False
            )

            # Get evaluation results
            try:
                self.evals_result = self.model.evals_result()
            except:
                self.evals_result = {}

            # Get feature importance
            self.feature_importance = self.model.feature_importances_

            # Make predictions
            self.predictions['train'] = self.model.predict_proba(X_train_flat)[:, 1]
            self.predictions['val'] = self.model.predict_proba(X_val_flat)[:, 1]

            # Store training history
            self._store_training_history()

            # Evaluate
            self.evaluate(y_train, self.predictions['train'], "Train", find_threshold=True)
            self.evaluate(y_val, self.predictions['val'], "Validation")
            
            self.is_trained = True
            print(f"  ✓ {self.name} training completed")

            return self
            
        except Exception as e:
            print(f"  ✗ Error training XGBoost: {e}")
            self.training_error = str(e)
            # Return safe predictions
            self.predictions['train'] = np.full(len(y_train), 0.5)
            self.predictions['val'] = np.full(len(y_val), 0.5)
            return self
    
    def _store_training_history(self):
        """Store XGBoost training history"""
        if self.evals_result:
            for key, value in self.evals_result.items():
                if 'logloss' in key:
                    if 'train' in key:
                        self.training_history['train_loss'] = value
                    elif 'val' in key:
                        self.training_history['val_loss'] = value
                elif 'error' in key or 'auc' in key:
                    if 'train' in key:
                        self.training_history['train_accuracy'] = [1 - v for v in value]
                    elif 'val' in key:
                        self.training_history['val_accuracy'] = [1 - v for v in value]

            # Create epochs if we have training history
            if 'train_loss' in self.training_history:
                self.training_history['epochs'] = list(range(1, len(self.training_history['train_loss']) + 1))
    
    def predict(self, X):
        """Make predictions"""
        if not self.is_trained:
            raise ValueError("Model not trained yet")
        
        X_flat = X.reshape(X.shape[0], -1)
        return self.model.predict_proba(X_flat)[:, 1]

class XGBoostRegressorModel(BaseModel):
    """XGBoost Regressor for predicting residuals"""
    
    def __init__(self):
        super().__init__("XGBoostRegressor")
        self.evals_result = None
        self.architecture_info = {
            'type': 'XGBoostRegressor',
            'parameters': {
                'learning_rate': XGB_LEARNING_RATE,
                'max_depth': XGB_MAX_DEPTH,
                'n_estimators': XGB_N_ESTIMATORS,
                'subsample': XGB_SUBSAMPLE,
                'colsample_bytree': XGB_COLSAMPLE_BYTREE,
                'objective': 'reg:squarederror'
            },
            'description': 'XGBoost Regressor for residual prediction'
        }

    def train(self, X_train, y_train, X_val=None, y_val=None):
        """Train XGBoost regressor model"""
        print(f"\nTraining {self.name} regressor model...")
        
        try:
            X_train_flat = X_train.reshape(X_train.shape[0], -1)

            self.model = XGBRegressor(
                objective='reg:squarederror',
                learning_rate=XGB_LEARNING_RATE,
                max_depth=XGB_MAX_DEPTH,
                n_estimators=XGB_N_ESTIMATORS,
                subsample=XGB_SUBSAMPLE,
                colsample_bytree=XGB_COLSAMPLE_BYTREE,
                random_state=42,
                verbosity=0,
                n_jobs=-1
            )

            eval_set = []
            if X_val is not None and y_val is not None:
                X_val_flat = X_val.reshape(X_val.shape[0], -1)
                eval_set.append((X_val_flat, y_val))

            self.model.fit(X_train_flat, y_train,
                          eval_set=eval_set,
                          verbose=False)

            # Get evaluation results
            if eval_set:
                try:
                    self.evals_result = self.model.evals_result()
                except:
                    self.evals_result = {}

            self.predictions['train'] = self.model.predict(X_train_flat)
            if X_val is not None and y_val is not None:
                self.predictions['val'] = self.model.predict(X_val_flat)

            # Store training history
            if self.evals_result:
                for key, value in self.evals_result.items():
                    if 'rmse' in key or 'mae' in key:
                        if 'train' in key:
                            self.training_history['train_loss'] = value
                        elif 'val' in key:
                            self.training_history['val_loss'] = value

                # Create epochs if we have training history
                if 'train_loss' in self.training_history:
                    self.training_history['epochs'] = list(range(1, len(self.training_history['train_loss']) + 1))
            
            self.is_trained = True
            print(f"  ✓ {self.name} training completed")
            
            return self
            
        except Exception as e:
            print(f"  ✗ Error training {self.name}: {e}")
            self.training_error = str(e)
            return self

    def predict(self, X):
        """Make predictions"""
        if not self.is_trained:
            raise ValueError("Model not trained yet")
        
        X_flat = X.reshape(X.shape[0], -1)
        return self.model.predict(X_flat)

class RandomForestModel(BaseModel):
    """Random Forest Model with error handling"""
    
    def __init__(self):
        super().__init__("RandomForest")
        self.oob_scores = []
        self.architecture_info = {
            'type': 'Random Forest',
            'parameters': {
                'n_estimators': 100,
                'max_depth': 10,
                'min_samples_split': 5,
                'min_samples_leaf': 2,
                'oob_score': True
            },
            'description': 'Ensemble of decision trees with bagging'
        }
    
    def train(self, X_train, y_train, X_val, y_val):
        """Train Random Forest model"""
        print(f"\nTraining {self.name} model...")
        
        try:
            X_train_flat = X_train.reshape(X_train.shape[0], -1)
            X_val_flat = X_val.reshape(X_val.shape[0], -1)

            y_train_binary = (y_train > 0.5).astype(int)
            y_val_binary = (y_val > 0.5).astype(int)

            # Train the model
            self.model = RandomForestClassifier(
                n_estimators=100,
                max_depth=10,
                min_samples_split=5,
                min_samples_leaf=2,
                random_state=42,
                oob_score=True,
                n_jobs=-1
            )

            self.model.fit(X_train_flat, y_train_binary)

            # Get OOB score
            oob_score = self.model.oob_score_ if hasattr(self.model, 'oob_score_') else 0
            self.oob_scores = [oob_score]

            # Get predictions
            self.predictions['train'] = self.model.predict_proba(X_train_flat)[:, 1]
            self.predictions['val'] = self.model.predict_proba(X_val_flat)[:, 1]

            # Calculate metrics
            train_acc = accuracy_score(y_train_binary, (self.predictions['train'] > 0.5).astype(int))
            val_acc = accuracy_score(y_val_binary, (self.predictions['val'] > 0.5).astype(int))

            # Store training history
            self.training_history['oob_scores'] = self.oob_scores
            self.training_history['train_accuracy'] = [train_acc]
            self.training_history['val_accuracy'] = [val_acc]
            self.training_history['train_loss'] = [1 - train_acc]
            self.training_history['val_loss'] = [1 - val_acc]
            self.training_history['n_trees'] = [100]
            self.training_history['epochs'] = [1]

            # Evaluate
            self.evaluate(y_train, self.predictions['train'], "Train", find_threshold=True)
            self.evaluate(y_val, self.predictions['val'], "Validation")
            
            self.is_trained = True
            print(f"  ✓ {self.name} training completed")

            return self
            
        except Exception as e:
            print(f"  ✗ Error training {self.name}: {e}")
            self.training_error = str(e)
            return self
    
    def predict(self, X):
        """Make predictions"""
        if not self.is_trained:
            raise ValueError("Model not trained yet")
        
        X_flat = X.reshape(X.shape[0], -1)
        return self.model.predict_proba(X_flat)[:, 1]

class GradientBoostingModel(BaseModel):
    """Gradient Boosting Model - FIXED VERSION"""

    def __init__(self):
        super().__init__("GradientBoosting")
        self.staged_train_scores = []
        self.staged_val_scores = []
        self.architecture_info = {
            'type': 'Gradient Boosting',
            'parameters': {
                'n_estimators': 100,
                'learning_rate': 0.1,
                'max_depth': 3,
                'random_state': 42
            },
            'description': 'Gradient Boosting classifier'
        }

    def build_model(self):
        """Build Gradient Boosting model"""
        self.model = GradientBoostingClassifier(
            n_estimators=100,
            learning_rate=0.1,
            max_depth=3,
            random_state=42,
            verbose=0
        )
        return self.model

    def train(self, X_train, y_train, X_val, y_val):
        """Train Gradient Boosting model - FIXED VERSION"""
        print(f"\nTraining {self.name} model...")

        try:
            X_train_flat = X_train.reshape(X_train.shape[0], -1)
            X_val_flat = X_val.reshape(X_val.shape[0], -1)

            y_train_binary = (y_train > 0.5).astype(int)
            y_val_binary = (y_val > 0.5).astype(int)

            # Build and train the model
            self.build_model()
            self.model.fit(X_train_flat, y_train_binary)

            # Store staged predictions for training history
            self.staged_train_scores = []
            self.staged_val_scores = []

            # Get predictions at each stage for training history
            for i, y_pred in enumerate(self.model.staged_predict_proba(X_train_flat)):
                train_acc = accuracy_score(y_train_binary, (y_pred[:, 1] > 0.5).astype(int))
                self.staged_train_scores.append(train_acc)

            for i, y_pred in enumerate(self.model.staged_predict_proba(X_val_flat)):
                val_acc = accuracy_score(y_val_binary, (y_pred[:, 1] > 0.5).astype(int))
                self.staged_val_scores.append(val_acc)

            # Get final predictions
            self.predictions['train'] = self.model.predict_proba(X_train_flat)[:, 1]
            self.predictions['val'] = self.model.predict_proba(X_val_flat)[:, 1]

            # Calculate final metrics for training history
            train_acc = accuracy_score(y_train_binary, (self.predictions['train'] > 0.5).astype(int))
            val_acc = accuracy_score(y_val_binary, (self.predictions['val'] > 0.5).astype(int))

            # Store training history using staged predictions
            self.training_history['epochs'] = list(range(1, len(self.staged_train_scores) + 1))
            self.training_history['train_accuracy'] = self.staged_train_scores
            self.training_history['val_accuracy'] = self.staged_val_scores
            self.training_history['train_loss'] = [1 - acc for acc in self.staged_train_scores]
            self.training_history['val_loss'] = [1 - acc for acc in self.staged_val_scores]

            # Evaluate
            self.evaluate(y_train, self.predictions['train'], "Train", find_threshold=True)
            self.evaluate(y_val, self.predictions['val'], "Validation")
            
            self.is_trained = True
            print(f"  ✓ {self.name} training completed")

            return self
            
        except Exception as e:
            print(f"  ✗ Error training {self.name}: {e}")
            self.training_error = str(e)
            return self

    def predict(self, X):
        """Make predictions"""
        if not self.is_trained:
            raise ValueError("Model not trained yet")
        
        X_flat = X.reshape(X.shape[0], -1)
        return self.model.predict_proba(X_flat)[:, 1]

    def get_model_summary(self):
        """Get model summary"""
        if self.model is not None:
            self.model_summary = f"Gradient Boosting Model Summary:\n"
            self.model_summary += f"Number of estimators: {self.model.n_estimators_}\n"
            self.model_summary += f"Learning rate: {self.model.learning_rate}\n"
            self.model_summary += f"Max depth: {self.model.max_depth}\n"
            self.model_summary += f"Training stages: {len(self.staged_train_scores)}\n"
        return self.model_summary

class SVMModel(BaseModel):
    """Support Vector Machine Model"""

    def __init__(self):
        super().__init__("SVM")
        self.architecture_info = {
            'type': 'Support Vector Machine',
            'parameters': {
                'C': 1.0,
                'kernel': 'rbf',
                'gamma': 'scale'
            },
            'description': 'Support Vector Classifier'
        }

    def train(self, X_train, y_train, X_val, y_val):
        """Train SVM model"""
        print(f"\nTraining {self.name} model...")

        try:
            X_train_flat = X_train.reshape(X_train.shape[0], -1)
            X_val_flat = X_val.reshape(X_val.shape[0], -1)

            y_train_binary = (y_train > 0.5).astype(int)
            y_val_binary = (y_val > 0.5).astype(int)

            self.model = SVC(
                C=1.0,
                kernel='rbf',
                gamma='scale',
                probability=True,
                random_state=42
            )

            self.model.fit(X_train_flat, y_train_binary)

            self.predictions['train'] = self.model.predict_proba(X_train_flat)[:, 1]
            self.predictions['val'] = self.model.predict_proba(X_val_flat)[:, 1]

            # For SVM, we don't have epoch-based training history
            # But we can store a simple history
            self.training_history['epochs'] = [1]
            self.training_history['train_accuracy'] = [accuracy_score(y_train_binary,
                                                                     (self.predictions['train'] > 0.5).astype(int))]
            self.training_history['val_accuracy'] = [accuracy_score(y_val_binary,
                                                                   (self.predictions['val'] > 0.5).astype(int))]
            self.training_history['train_loss'] = [1 - self.training_history['train_accuracy'][0]]
            self.training_history['val_loss'] = [1 - self.training_history['val_accuracy'][0]]

            # Evaluate
            self.evaluate(y_train, self.predictions['train'], "Train", find_threshold=True)
            self.evaluate(y_val, self.predictions['val'], "Validation")
            
            self.is_trained = True
            print(f"  ✓ {self.name} training completed")

            return self
            
        except Exception as e:
            print(f"  ✗ Error training {self.name}: {e}")
            self.training_error = str(e)
            return self

    def predict(self, X):
        """Make predictions"""
        if not self.is_trained:
            raise ValueError("Model not trained yet")
        
        X_flat = X.reshape(X.shape[0], -1)
        return self.model.predict_proba(X_flat)[:, 1]

class MLPModel(BaseModel):
    """Multi-Layer Perceptron Model"""

    def __init__(self):
        super().__init__("MLP")
        self.architecture_info = {
            'type': 'Multi-Layer Perceptron',
            'parameters': {
                'hidden_layer_sizes': (100, 50),
                'activation': 'relu',
                'solver': 'adam',
                'alpha': 0.0001,
                'learning_rate': 'constant'
            },
            'description': 'Neural network with multiple hidden layers'
        }

    def train(self, X_train, y_train, X_val, y_val):
        """Train MLP model"""
        print(f"\nTraining {self.name} model...")

        try:
            X_train_flat = X_train.reshape(X_train.shape[0], -1)
            X_val_flat = X_val.reshape(X_val.shape[0], -1)

            y_train_binary = (y_train > 0.5).astype(int)
            y_val_binary = (y_val > 0.5).astype(int)

            self.model = MLPClassifier(
                hidden_layer_sizes=(100, 50),
                activation='relu',
                solver='adam',
                alpha=0.0001,
                learning_rate='constant',
                max_iter=100,
                random_state=42,
                early_stopping=True,
                validation_fraction=0.1,
                n_iter_no_change=10
            )

            self.model.fit(X_train_flat, y_train_binary)

            self.predictions['train'] = self.model.predict_proba(X_train_flat)[:, 1]
            self.predictions['val'] = self.model.predict_proba(X_val_flat)[:, 1]

            # MLP has loss curve in loss_curve_ attribute
            if hasattr(self.model, 'loss_curve_'):
                self.training_history['train_loss'] = self.model.loss_curve_
                self.training_history['epochs'] = list(range(1, len(self.model.loss_curve_) + 1))

                # For validation, we can use validation_scores_ if available
                if hasattr(self.model, 'validation_scores_'):
                    val_scores = self.model.validation_scores_
                    self.training_history['val_accuracy'] = val_scores

            # Store accuracy
            train_acc = accuracy_score(y_train_binary, (self.predictions['train'] > 0.5).astype(int))
            val_acc = accuracy_score(y_val_binary, (self.predictions['val'] > 0.5).astype(int))

            self.training_history['train_accuracy'] = [train_acc]
            self.training_history['val_accuracy'] = [val_acc]

            # Evaluate
            self.evaluate(y_train, self.predictions['train'], "Train", find_threshold=True)
            self.evaluate(y_val, self.predictions['val'], "Validation")
            
            self.is_trained = True
            print(f"  ✓ {self.name} training completed")

            return self
            
        except Exception as e:
            print(f"  ✗ Error training {self.name}: {e}")
            self.training_error = str(e)
            return self

    def predict(self, X):
        """Make predictions"""
        if not self.is_trained:
            raise ValueError("Model not trained yet")
        
        X_flat = X.reshape(X.shape[0], -1)
        return self.model.predict_proba(X_flat)[:, 1]

class ProphetModel(BaseModel):
    """Enhanced Prophet Model with robust error handling"""
    
    def __init__(self):
        super().__init__("Prophet")
        self.prophet = None
        self.scaler_mean = None
        self.scaler_std = None
        self.y_min = None
        self.y_max = None
        self.architecture_info = {
            'type': 'Prophet',
            'parameters': {
                'growth': PROPHET_GROWTH,
                'seasonality_mode': PROPHET_SEASONALITY_MODE,
                'yearly_seasonality': PROPHET_YEARLY_SEASONALITY,
                'weekly_seasonality': PROPHET_WEEKLY_SEASONALITY,
                'daily_seasonality': PROPHET_DAILY_SEASONALITY,
                'seasonality_prior_scale': PROPHET_SEASONALITY_PRIOR_SCALE,
                'changepoint_prior_scale': PROPHET_CHANGE_POINT_PRIOR_SCALE,
                'holidays_prior_scale': PROPHET_HOLIDAYS_PRIOR_SCALE,
                'mcmc_samples': PROPHET_MCMC_SAMPLES
            },
            'description': 'Facebook Prophet time series forecasting model adapted for classification'
        }
    
    def prepare_y_for_prophet(self, y):
        """Transform binary classification labels to suitable range for Prophet"""
        # Check if y is already continuous
        unique_vals = np.unique(y)
        if len(unique_vals) > 10:  # Likely continuous
            y_mean = np.mean(y)
            y_std = np.std(y) + 1e-7
            y_scaled = (y - y_mean) / y_std
            y_scaled = np.clip(y_scaled, -5, 5)
            return y_scaled, False

        # Binary classification case (0/1)
        epsilon = 1e-5
        y_safe = np.clip(y, epsilon, 1 - epsilon)
        y_logit = np.log(y_safe / (1 - y_safe))
        y_scaled = np.clip(y_logit, -5, 5)
        return y_scaled, True
    
    def inverse_transform_y(self, y_scaled, is_binary=True):
        """Inverse transform for predictions"""
        if is_binary:
            y_prob = 1 / (1 + np.exp(-y_scaled))
            return np.clip(y_prob, 0.001, 0.999)
        else:
            return y_scaled
    
    def train(self, dates_train, y_train, dates_val=None, y_val=None):
        """Train Prophet model with robust error handling"""
        print(f"\nTraining {self.name} model...")
        
        try:
            # Prepare y values for Prophet
            y_train_transformed, is_binary = self.prepare_y_for_prophet(y_train)
            self.is_binary = is_binary

            # Create Prophet dataframe
            prophet_df = pd.DataFrame({
                'ds': pd.to_datetime(dates_train),
                'y': y_train_transformed
            })

            # Handle missing values
            if prophet_df.isnull().any().any():
                prophet_df = prophet_df.fillna(method='ffill').fillna(method='bfill')

            # Create Prophet model
            self.prophet = Prophet(
                growth=PROPHET_GROWTH,
                seasonality_mode=PROPHET_SEASONALITY_MODE,
                yearly_seasonality=PROPHET_YEARLY_SEASONALITY,
                weekly_seasonality=PROPHET_WEEKLY_SEASONALITY,
                daily_seasonality=PROPHET_DAILY_SEASONALITY,
                seasonality_prior_scale=PROPHET_SEASONALITY_PRIOR_SCALE,
                changepoint_prior_scale=PROPHET_CHANGE_POINT_PRIOR_SCALE,
                holidays_prior_scale=PROPHET_HOLIDAYS_PRIOR_SCALE,
                mcmc_samples=PROPHET_MCMC_SAMPLES
            )

            # Fit model with error handling
            try:
                self.prophet.fit(prophet_df, iter=300)
                print("  ✓ Prophet model fitted successfully")
            except Exception as e:
                print(f"  ⚠ Prophet fitting failed, trying simplified model: {e}")
                # Try with simpler parameters
                self.prophet = Prophet(
                    growth='linear',
                    seasonality_mode='additive',
                    yearly_seasonality=False,
                    weekly_seasonality=False,
                    daily_seasonality=False
                )
                self.prophet.fit(prophet_df, iter=200)
                print("  ✓ Prophet model fitted with simplified parameters")

            # Make predictions on training data
            forecast = self.prophet.predict(prophet_df)
            train_preds_transformed = forecast['yhat'].values
            train_preds = self.inverse_transform_y(train_preds_transformed, is_binary)
            self.predictions['train'] = train_preds

            # Store transformation parameters
            self.scaler_mean = train_preds_transformed.mean()
            self.scaler_std = train_preds_transformed.std() + 1e-7

            # Validation predictions
            if dates_val is not None and y_val is not None:
                val_df = pd.DataFrame({'ds': pd.to_datetime(dates_val)})
                val_forecast = self.prophet.predict(val_df)
                val_preds_transformed = val_forecast['yhat'].values
                val_preds = self.inverse_transform_y(val_preds_transformed, is_binary)
                self.predictions['val'] = val_preds

            # Calculate metrics
            if len(y_train) > 0:
                self.evaluate(y_train, train_preds, "Train", find_threshold=True)

            if dates_val is not None and y_val is not None and len(y_val) > 0:
                self.evaluate(y_val, val_preds, "Validation")

            # Store training history
            self.training_history['epochs'] = [1]
            self.training_history['train_accuracy'] = [self.metrics.get('Train', {}).get('Accuracy', 0)]
            self.training_history['val_accuracy'] = [self.metrics.get('Validation', {}).get('Accuracy', 0)]
            
            self.is_trained = True
            print(f"  ✓ Training completed for {self.name}")
            
            return self
            
        except Exception as e:
            print(f"  ✗ Error training {self.name}: {str(e)}")
            self.training_error = str(e)
            # Return safe predictions
            self.predictions['train'] = np.full(len(y_train), 0.5)
            if dates_val is not None and y_val is not None:
                self.predictions['val'] = np.full(len(y_val), 0.5)
            return self
    
    def predict(self, dates):
        """Make predictions with error handling"""
        if not self.is_trained:
            print("  ⚠ Prophet model not trained, returning default predictions")
            return np.full(len(dates), 0.5)

        try:
            df = pd.DataFrame({'ds': pd.to_datetime(dates)})
            forecast = self.prophet.predict(df)
            preds_transformed = forecast['yhat'].values
            preds = self.inverse_transform_y(preds_transformed, getattr(self, 'is_binary', True))
            return np.clip(preds, 0.001, 0.999)
        except Exception as e:
            print(f"  ⚠ Error in Prophet prediction: {str(e)}")
            return np.full(len(dates), 0.5)

# ============================================
# HYBRID MODELS WITH ARCHITECTURE INFO
# ============================================

class FixedHybridResidualModel(BaseModel):
    """Fixed Hybrid model using residuals with proper probability handling"""

    def __init__(self, name, model1, model2):
        super().__init__(name)
        self.model1 = model1
        self.model2 = model2
        self.residuals = {}

        # Store architecture information
        self.architecture_info = {
            'type': 'Hybrid',
            'components': [
                {'name': model1.name, 'type': type(model1).__name__},
                {'name': model2.name, 'type': type(model2).__name__}
            ],
            'description': f'Hybrid model combining {model1.name} and {model2.name} using residual learning'
        }

        # Copy architecture info from components if available
        if hasattr(model1, 'architecture_info'):
            self.architecture_info['component1_details'] = model1.architecture_info
        if hasattr(model2, 'architecture_info'):
            self.architecture_info['component2_details'] = model2.architecture_info

    def calculate_residuals(self, y_true, pred_prob):
        """Calculate residuals in probability space with better handling"""
        eps = 1e-7
        pred_prob = np.clip(pred_prob, eps, 1-eps)
        # Scale residuals to avoid extreme values
        residuals = (y_true - pred_prob) * 0.5  # Scale down residuals
        return residuals

    def train(self, X_train, y_train, X_val, y_val, dates_train=None, dates_val=None):
        """Train hybrid model using residuals with proper handling"""
        print(f"\nTraining {self.name} hybrid model...")

        # Train model1 with appropriate arguments
        if isinstance(self.model1, ProphetModel):
            if dates_train is None or dates_val is None:
                raise ValueError("Prophet requires dates for training")
            self.model1.train(dates_train, y_train, dates_val, y_val)
        else:
            self.model1.train(X_train, y_train, X_val, y_val)

        # Calculate residuals from model1
        self.residuals['train'] = self.calculate_residuals(y_train, self.model1.predictions['train'])
        self.residuals['val'] = self.calculate_residuals(y_val, self.model1.predictions['val'])

        # Train model2 on residuals - ensure we don't have extreme values
        train_residuals = np.clip(self.residuals['train'], -0.5, 0.5)
        val_residuals = np.clip(self.residuals['val'], -0.5, 0.5)

        # FIX: Ensure classifiers are trained on binary residuals (sign), not continuous values
        if isinstance(self.model2, XGBoostRegressorModel):
            # For regression models, train directly on residuals
            self.model2.train(X_train, train_residuals, X_val, val_residuals)
        else:
            # For classification models, convert residuals to binary (sign of the error)
            residuals_binary = (train_residuals > 0).astype(int)
            residuals_val_binary = (val_residuals > 0).astype(int)
            self.model2.train(X_train, residuals_binary, X_val, residuals_val_binary)

        # Combine predictions: model1 + model2's prediction of residuals
        train_combined = self.model1.predictions['train'] + self.model2.predictions['train']
        val_combined = self.model1.predictions['val'] + self.model2.predictions['val']

        # Apply sigmoid to combined predictions with proper scaling
        self.predictions['train'] = 1 / (1 + np.exp(-train_combined))
        self.predictions['val'] = 1 / (1 + np.exp(-val_combined))

        # Clip to valid probability range but avoid extremes
        self.predictions['train'] = np.clip(self.predictions['train'], 0.05, 0.95)
        self.predictions['val'] = np.clip(self.predictions['val'], 0.05, 0.95)

        # Ensure we don't have all zeros
        if np.all(self.predictions['train'] == 0):
            print(f"Warning: {self.name} has all zero predictions for training set")
            self.predictions['train'] = np.full_like(self.predictions['train'], 0.5)

        if np.all(self.predictions['val'] == 0):
            print(f"Warning: {self.name} has all zero predictions for validation set")
            self.predictions['val'] = np.full_like(self.predictions['val'], 0.5)

        # Combine model summaries
        self.get_model_summary()

        # Store training history from both components
        self.combine_training_histories()
        
        self.is_trained = True
        print(f"  ✓ {self.name} training completed")

        return self

    def combine_training_histories(self):
        """Combine training histories from both models"""
        # Start with model1 history
        if hasattr(self.model1, 'training_history'):
            for key in ['epochs', 'train_loss', 'val_loss', 'train_accuracy', 'val_accuracy']:
                if key in self.model1.training_history:
                    self.training_history[key] = self.model1.training_history[key]

        # Add model2 metrics if available
        if hasattr(self.model2, 'training_history'):
            if 'train_metrics' in self.model2.training_history:
                self.training_history['model2_train_metrics'] = self.model2.training_history['train_metrics']
            if 'val_metrics' in self.model2.training_history:
                self.training_history['model2_val_metrics'] = self.model2.training_history['val_metrics']

    def predict(self, X, dates=None):
        """Make predictions with hybrid model"""
        # Get predictions from model1
        if isinstance(self.model1, ProphetModel):
            if dates is None:
                raise ValueError("Prophet requires dates for prediction")
            pred1 = self.model1.predict(dates)
        else:
            pred1 = self.model1.predict(X)

        # Get residual predictions from model2
        pred2 = self.model2.predict(X)

        # Combine predictions and apply sigmoid
        hybrid_pred = pred1 + pred2
        hybrid_pred = 1 / (1 + np.exp(-hybrid_pred))
        hybrid_pred = np.clip(hybrid_pred, 0.05, 0.95)  # Avoid extremes

        # Check for all zeros
        if np.all(hybrid_pred == 0):
            print(f"Warning: {self.name} prediction resulted in all zeros, using 0.5")
            hybrid_pred = np.full_like(hybrid_pred, 0.5)

        return hybrid_pred

    def get_model_summary(self):
        """Get hybrid model summary"""
        self.model_summary = f"{self.name} Hybrid Model Summary:\n"
        self.model_summary += f"Model 1: {self.model1.name}\n"
        self.model_summary += f"Model 2: {self.model2.name}\n\n"

        # Add Model 1 summary
        self.model_summary += f"=== Model 1 ({self.model1.name}) ===\n"
        if hasattr(self.model1, 'get_model_summary'):
            self.model_summary += self.model1.get_model_summary() + "\n"

        # Add Model 2 summary
        self.model_summary += f"\n=== Model 2 ({self.model2.name}) ===\n"
        if hasattr(self.model2, 'get_model_summary'):
            self.model_summary += self.model2.get_model_summary() + "\n"

        return self.model_summary

