# ENSEMBLE MODELS
# ============================================

class EnsembleAverageHybrid(BaseModel):
    """Ensemble Hybrid Model - Average of multiple model predictions"""

    def __init__(self, name, models):
        super().__init__(name)
        self.models = models
        self.weights = None  # Equal weights by default

        self.architecture_info = {
            'type': 'EnsembleAverage',
            'components': [{'name': m.name, 'type': type(m).__name__} for m in models],
            'description': 'Simple ensemble averaging of multiple models'
        }

    def train(self, X_train, y_train, X_val, y_val, dates_train=None, dates_val=None):
        """Train ensemble model - just store predictions from already trained models"""
        print(f"\nTraining {self.name} ensemble model...")

        # Check if all models are already trained
        for model in self.models:
            if not hasattr(model, 'predictions') or 'train' not in model.predictions:
                print(f"Warning: Model {model.name} not trained yet, training now...")
                if isinstance(model, ProphetModel):
                    if dates_train is None or dates_val is None:
                        # Create dummy dates if not provided
                        dates_train = np.arange(len(X_train))
                        dates_val = np.arange(len(X_val))
                    model.train(dates_train, y_train, dates_val, y_val)
                else:
                    model.train(X_train, y_train, X_val, y_val)

        # Calculate average predictions
        train_predictions = []
        val_predictions = []

        for model in self.models:
            if 'train' in model.predictions:
                train_predictions.append(model.predictions['train'])
            if 'val' in model.predictions:
                val_predictions.append(model.predictions['val'])

        if train_predictions:
            self.predictions['train'] = np.mean(train_predictions, axis=0)
        if val_predictions:
            self.predictions['val'] = np.mean(val_predictions, axis=0)

        # Store training history (average of component histories)
        self.combine_training_histories()
        
        self.is_trained = True
        print(f"  ✓ {self.name} training completed")

        return self

    def combine_training_histories(self):
        """Combine training histories from all models"""
        all_epochs = []
        for model in self.models:
            if hasattr(model, 'training_history') and 'epochs' in model.training_history:
                all_epochs.extend(model.training_history['epochs'])

        if all_epochs:
            self.training_history['epochs'] = sorted(set(all_epochs))

    def predict(self, X, dates=None):
        """Make ensemble predictions"""
        predictions = []

        for model in self.models:
            if isinstance(model, ProphetModel):
                if dates is None:
                    raise ValueError("Prophet requires dates for prediction")
                pred = model.predict(dates)
            else:
                pred = model.predict(X)
            predictions.append(pred)

        return np.mean(predictions, axis=0)


# New ensemble hybrids
class DeepLearningEnsemble(EnsembleAverageHybrid):
    """Ensemble of all deep learning models"""
    def __init__(self, lstm, bilstm, gru, cnn_lstm):
        super().__init__("DeepLearningEnsemble", [lstm, bilstm, gru, cnn_lstm])

class TreeBasedEnsemble(EnsembleAverageHybrid):
    """Ensemble of all tree-based models"""
    def __init__(self, xgboost, rf, gb):
        super().__init__("TreeBasedEnsemble", [xgboost, rf, gb])

class AllModelsEnsemble(EnsembleAverageHybrid):
    """Ensemble of all models"""
    def __init__(self, *models):
        super().__init__("AllModelsEnsemble", list(models))


class StackedEnsembleHybrid(BaseModel):
    """Stacked Ensemble using meta-learner"""

    def __init__(self, name, base_models, meta_model=None):
        super().__init__(name)
        self.base_models = base_models
        self.meta_model = meta_model if meta_model else XGBClassifier()
        self.meta_model_trained = False

        self.architecture_info = {
            'type': 'StackedEnsemble',
            'base_models': [{'name': m.name, 'type': type(m).__name__} for m in base_models],
            'meta_model': type(meta_model).__name__ if meta_model else 'XGBClassifier',
            'description': 'Stacked ensemble with meta-learner'
        }

    def train(self, X_train, y_train, X_val, y_val, dates_train=None, dates_val=None):
        """Train stacked ensemble"""
        print(f"\nTraining {self.name} stacked ensemble...")

        # Ensure base models are trained
        for model in self.base_models:
            if not hasattr(model, 'predictions') or 'train' not in model.predictions:
                print(f"Training base model: {model.name}")
                if isinstance(model, ProphetModel):
                    if dates_train is None or dates_val is None:
                        # Create dummy dates if not provided
                        dates_train = np.arange(len(X_train))
                        dates_val = np.arange(len(X_val))
                    model.train(dates_train, y_train, dates_val, y_val)
                else:
                    model.train(X_train, y_train, X_val, y_val)

        # Create meta-features from base model predictions
        X_train_meta = []
        X_val_meta = []

        for model in self.base_models:
            if 'train' in model.predictions:
                X_train_meta.append(model.predictions['train'].reshape(-1, 1))
            if 'val' in model.predictions:
                X_val_meta.append(model.predictions['val'].reshape(-1, 1))

        X_train_meta = np.hstack(X_train_meta) if X_train_meta else np.array([])
        X_val_meta = np.hstack(X_val_meta) if X_val_meta else np.array([])

        # Train meta-model if we have meta-features
        if len(X_train_meta) > 0 and len(y_train) > 0:
            y_train_binary = (y_train > 0.5).astype(int)
            y_val_binary = (y_val > 0.5).astype(int) if len(y_val) > 0 else None

            self.meta_model.fit(X_train_meta, y_train_binary)
            self.meta_model_trained = True

            # Get predictions
            if len(X_train_meta) > 0:
                self.predictions['train'] = self.meta_model.predict_proba(X_train_meta)[:, 1]
            if len(X_val_meta) > 0 and y_val_binary is not None:
                self.predictions['val'] = self.meta_model.predict_proba(X_val_meta)[:, 1]

        return self

    def predict(self, X, dates=None):
        """Make stacked predictions"""
        if not self.meta_model_trained:
            raise ValueError("Meta-model not trained yet")

        # Get predictions from all base models
        base_predictions = []
        for model in self.base_models:
            if isinstance(model, ProphetModel):
                if dates is None:
                    raise ValueError("Prophet requires dates for prediction")
                pred = model.predict(dates)
            else:
                pred = model.predict(X)
            base_predictions.append(pred.reshape(-1, 1))

        X_meta = np.hstack(base_predictions) if base_predictions else np.array([])

        if len(X_meta) > 0:
            return self.meta_model.predict_proba(X_meta)[:, 1]
        else:
            return np.zeros(len(X) if X is not None else len(dates)) + 0.5

# ============================================
# MODEL TRAINING MANAGER
# ============================================

class ModelTrainingManager:
    """Manages training of all models with comprehensive error handling"""
    
    def __init__(self):
        self.models = {}
        self.trained_models = {}
        self.failed_models = {}
        self.training_summary = {}
        
        # Create checkpoints directory
        os.makedirs('checkpoints', exist_ok=True)
        
    def create_all_models(self):
        """Create ALL model instances - includes every model from your original code"""
        print("Creating all models...")
        
        # Create base models
        base_models = {
            'LSTM': LSTMModel(),
            'BiLSTM': BiLSTMModel(),
            'GRU': GRUModel(),
            'CNN-LSTM': CNNLSTMModel(),
            'XGBoost': XGBoostModel(),
            'RandomForest': RandomForestModel(),
            'GradientBoosting': GradientBoostingModel(),
            'SVM': SVMModel(),
            'MLP': MLPModel(),
            'Prophet': ProphetModel(),
            'XGBoostRegressor': XGBoostRegressorModel(),
        }
        
        # Create hybrid models
        hybrid_models = self.create_hybrid_models(base_models)
        
        # Combine all models
        self.models = {**base_models, **hybrid_models}
        
        print(f"Created {len(self.models)} models total")
        return self.models
    
    def create_hybrid_models(self, base_models):
        """Create hybrid model instances"""
        hybrids = {
            # Basic hybrids
            'Prophet-LSTM': ProphetLSTMHybrid(base_models['Prophet'], base_models['LSTM']),
            'Prophet-BiLSTM': ProphetBiLSTMHybrid(base_models['Prophet'], base_models['BiLSTM']),
            'LSTM-BiLSTM': LSTMBiLSTMHybrid(base_models['LSTM'], base_models['BiLSTM']),
            'Prophet-XGBoost': ProphetXGBoostHybrid(base_models['Prophet'], base_models['XGBoostRegressor']),
            
            # New hybrids
            'LSTM-GradientBoosting': LSTMGradientBoostingHybrid(base_models['LSTM'], base_models['GradientBoosting']),
            'BiLSTM-XGBoost': BiLSTMXGBoostHybrid(base_models['BiLSTM'], base_models['XGBoost']),
            'CNN-LSTM-XGBoost': CNNLSTMXGBoostHybrid(base_models['CNN-LSTM'], base_models['XGBoost']),
            'GRU-XGBoost': GRUXGBoostHybrid(base_models['GRU'], base_models['XGBoost']),
            'LSTM-GRU': LSTMGRUHybrid(base_models['LSTM'], base_models['GRU']),
            
            # Prophet hybrids
            'Prophet-GRU': ProphetGRUHybrid(base_models['Prophet'], base_models['GRU']),
            'Prophet-CNN-LSTM': ProphetCNN_LSTMHybrid(base_models['Prophet'], base_models['CNN-LSTM']),
            'Prophet-GradientBoosting': ProphetGradientBoostingHybrid(base_models['Prophet'], base_models['GradientBoosting']),
            'Prophet-RandomForest': ProphetRandomForestHybrid(base_models['Prophet'], base_models['RandomForest']),
            'Prophet-MLP': ProphetMLPHybrid(base_models['Prophet'], base_models['MLP']),
        }
        
        return hybrids
    
    def train_all_models(self, X_train, y_train, X_val, y_val, dates_train=None, dates_val=None):
        """Train ALL models with robust error handling"""
        print(f"\n{'='*80}")
        print("🚀 STARTING COMPREHENSIVE MODEL TRAINING SESSION")
        print(f"{'='*80}")
        
        # Initialize memory management
        MemoryManager.initialize()
        
        # Create models if not already created
        if not self.models:
            self.create_all_models()
        
        total_models = len(self.models)
        print(f"📊 Total models to train: {total_models}")
        print(f"📊 Training samples: {len(X_train)}")
        print(f"📊 Validation samples: {len(X_val)}")
        print(f"{'='*80}")
        
        # Train each model
        for i, (name, model) in enumerate(self.models.items(), 1):
            try:
                print(f"\n[{i}/{total_models}] ▶ Training: {name}")
                print(f"{'-'*60}")
                
                start_time = pd.Timestamp.now()
                
                # Check if model requires dates (Prophet)
                if isinstance(model, ProphetModel):
                    if dates_train is None or dates_val is None:
                        print(f"  ⚠ Skipping {name}: Prophet requires dates")
                        self.failed_models[name] = "Missing dates"
                        continue
                    
                    # Train Prophet with dates
                    result = model.train(dates_train, y_train, dates_val, y_val)
                
                elif isinstance(model, FixedHybridResidualModel):
                    # Train hybrid models with dates if needed
                    result = model.train(X_train, y_train, X_val, y_val, dates_train, dates_val)
                
                else:
                    # Train standard models
                    result = model.train(X_train, y_train, X_val, y_val)
                
                end_time = pd.Timestamp.now()
                training_time = (end_time - start_time).total_seconds()
                
                # Check training result
                if hasattr(model, 'is_trained') and model.is_trained:
                    self.trained_models[name] = model
                    self.training_summary[name] = {
                        'status': 'success',
                        'training_time': training_time,
                        'metrics': model.metrics.get('Validation', {}),
                        'error': None
                    }
                    print(f"  ✅ {name} trained successfully ({training_time:.1f}s)")
                else:
                    error_msg = getattr(model, 'training_error', 'Unknown error')
                    self.failed_models[name] = error_msg
                    self.training_summary[name] = {
                        'status': 'failed',
                        'training_time': training_time,
                        'metrics': {},
                        'error': error_msg
                    }
                    print(f"  ❌ {name} failed: {error_msg}")
                
                # Force garbage collection between models
                MemoryManager.cleanup()
                
                # Small delay to let system recover
                import time
                time.sleep(1)
                
            except KeyboardInterrupt:
                print(f"\n⚠ Training interrupted by user")
                break
            except Exception as e:
                print(f"  ❗ Critical error training {name}: {str(e)}")
                self.failed_models[name] = str(e)
                self.training_summary[name] = {
                    'status': 'critical_error',
                    'training_time': 0,
                    'metrics': {},
                    'error': str(e)
                }
                import traceback
                traceback.print_exc()
                continue
        
        # Print comprehensive summary
        self._print_training_summary()
        
        return self.trained_models
    
    def _print_training_summary(self):
        """Print detailed training summary"""
        print(f"\n{'='*80}")
        print("📊 TRAINING SUMMARY REPORT")
        print(f"{'='*80}")
        
        # Overall statistics
        total_models = len(self.models)
        successful = len(self.trained_models)
        failed = len(self.failed_models)
        
        print(f"📈 Overall Statistics:")
        print(f"  • Total models: {total_models}")
        print(f"  • Successful: {successful} ({successful/total_models*100:.1f}%)")
        print(f"  • Failed: {failed} ({failed/total_models*100:.1f}%)")
        
        # Successful models details
        if self.trained_models:
            print(f"\n✅ Successfully Trained Models:")
            for name, model in self.trained_models.items():
                metrics = model.metrics.get('Validation', {})
                if metrics:
                    acc = metrics.get('Accuracy', 0)
                    f1 = metrics.get('F1', 0)
                    auc = metrics.get('AUC_ROC', 0)
                    print(f"  • {name}: Accuracy={acc:.4f}, F1={f1:.4f}, AUC={auc:.4f}")
        
        # Failed models details
        if self.failed_models:
            print(f"\n❌ Failed Models:")
            for name, error in self.failed_models.items():
                print(f"  • {name}: {error}")
        
        # Memory usage
        memory_usage = MemoryManager.get_memory_usage()
        print(f"\n💾 Memory Usage: {memory_usage:.2f} MB")
        
        # Recommendations
        print(f"\n💡 Recommendations:")
        if failed > successful:
            print(f"  • Check data quality and preprocessing")
            print(f"  • Reduce model complexity (units, layers)")
            print(f"  • Reduce batch size (current: {BATCH_SIZE})")
            print(f"  • Check for memory leaks")
        else:
            print(f"  • Training completed successfully!")
            print(f"  • Consider ensemble methods for improved performance")
        
        print(f"{'='*80}")
    
    def get_best_model(self, metric='F1'):
        """Get the best performing model based on metric"""
        best_model = None
        best_score = -1
        
        for name, model in self.trained_models.items():
            metrics = model.metrics.get('Validation', {})
            score = metrics.get(metric, -1)
            if score > best_score:
                best_score = score
                best_model = (name, model)
        
        return best_model
    
    def cleanup(self):
        """Clean up all models and resources"""
        print("\n🧹 Cleaning up resources...")
        
        for name, model in self.models.items():
            try:
                if hasattr(model, 'cleanup'):
                    model.cleanup()
            except:
                pass
        
        self.models.clear()
        self.trained_models.clear()
        self.failed_models.clear()
        MemoryManager.cleanup()
        
        print("✅ Cleanup completed")

# ============================================
# MAIN TRAINING FUNCTION
# ============================================

def train_all_models(X_train, y_train, X_val, y_val, dates_train=None, dates_val=None):
    """
    Main function to train ALL models safely
    
    Parameters:
    -----------
    X_train, X_val : numpy arrays
        3D arrays of shape (samples, timesteps, features) for sequence models
    y_train, y_val : numpy arrays
        Target values (binary classification)
    dates_train, dates_val : array-like, optional
        Dates for Prophet model
        
    Returns:
    --------
    dict: Trained models
    """
    
    # Create training manager
    manager = ModelTrainingManager()
    
    try:
        print("🧪 Initializing model training...")
        
        # Train all models
        trained_models = manager.train_all_models(
            X_train, y_train, 
            X_val, y_val,
            dates_train, dates_val
        )
        
        # Get best model
        best_model_info = manager.get_best_model('F1')
        if best_model_info:
            best_name, best_model = best_model_info
            print(f"\n🏆 Best Model: {best_name}")
            best_metrics = best_model.metrics.get('Validation', {})
            for metric, value in best_metrics.items():
                if metric != 'Threshold':
                    print(f"  {metric}: {value:.4f}")
        
        return trained_models
        
    except Exception as e:
        print(f"❌ Error in main training function: {e}")
        import traceback
        traceback.print_exc()
        return {}
        
    finally:
        # Always cleanup
        manager.cleanup()


